-- ============================================================
-- SEED: Módulo 18 — Nominalization (B2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'nominalization';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo nominalization não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: Verb → Noun (-tion / -sion)
  (cid,1,1,'gap_fill','The team conducted an _____ (investigate) of the crash site.','investigation',NULL,'"Investigate" → "investigation" (suffix -tion). Nominalization converts the verb to a noun.','easy'),
  (cid,1,2,'multiple_choice','The government announced the _____ of a new environmental policy.','introduction','["introduce","introducing","introduction","introduced"]','"Introduce" → "introduction." The noun form is required after "the" + "of."','easy'),
  (cid,1,3,'gap_fill','The _____ (apply) of this method produced consistent results.','application',NULL,'"Apply" → "application." → The application of this method.','easy'),
  (cid,1,4,'multiple_choice','Researchers focused on the _____ of historical data to predict future trends.','analysis','["analyze","analyzing","analysis","analyzed"]','"Analyze" → "analysis" (irregular nominalization). → the analysis of historical data.','medium'),
  (cid,1,5,'gap_fill','The _____ (pollute) of groundwater is a serious environmental concern.','pollution',NULL,'"Pollute" → "pollution." → The pollution of groundwater.','easy'),
  (cid,1,6,'multiple_choice','The study examined the _____ between stress and immune system function.','correlation','["correlate","correlating","correlated","correlation"]','"Correlate" → "correlation." Noun required after "the" in this context.','medium'),
  (cid,1,7,'gap_fill','The _____ (consume) of fossil fuels has increased dramatically since the Industrial Revolution.','consumption',NULL,'"Consume" → "consumption." → The consumption of fossil fuels.','easy'),
  (cid,1,8,'multiple_choice','The _____ of the new drug will be evaluated in a randomized controlled trial.','administration','["administer","administering","administration","administered"]','"Administer" → "administration." → The administration of the new drug.','medium'),

  -- BLOCK 2: Verb → Noun (-ment / -ance / -ence)
  (cid,2,9,'gap_fill','The _____ (develop) of renewable energy sources is essential for a sustainable future.','development',NULL,'"Develop" → "development" (suffix -ment). → The development of renewable energy.','easy'),
  (cid,2,10,'multiple_choice','The study measured the _____ of participants in completing cognitive tasks.','performance','["perform","performing","performance","performed"]','"Perform" → "performance" (suffix -ance). → the performance of participants.','easy'),
  (cid,2,11,'gap_fill','The _____ (achieve) of net-zero emissions by 2050 is a primary goal of the agreement.','achievement',NULL,'"Achieve" → "achievement" (suffix -ment). → The achievement of net-zero emissions.','easy'),
  (cid,2,12,'multiple_choice','The _____ of evidence in court requires strict adherence to procedural rules.','presentation','["present","presenting","presentation","presented"]','"Present" → "presentation" (suffix -tion). → The presentation of evidence in court.','medium'),
  (cid,2,13,'gap_fill','The _____ (manage) of natural resources requires both scientific expertise and political will.','management',NULL,'"Manage" → "management." → The management of natural resources.','easy'),
  (cid,2,14,'multiple_choice','The report highlighted the _____ of adequate funding for basic research.','importance','["important","importantly","importance","import"]','"Important" → "importance" (adjective → noun, suffix -ance). → the importance of adequate funding.','medium'),
  (cid,2,15,'gap_fill','The _____ (involve) of local communities in conservation efforts is critical.','involvement',NULL,'"Involve" → "involvement." → The involvement of local communities.','medium'),
  (cid,2,16,'multiple_choice','The _____ of scientific knowledge depends on the publication of peer-reviewed research.','advancement','["advance","advancing","advancement","advanced"]','"Advance" → "advancement" (suffix -ment). → The advancement of scientific knowledge.','medium'),

  -- BLOCK 3: Adjective → Noun (-ity / -ness / -ance)
  (cid,3,17,'gap_fill','The _____ (significant) of this finding cannot be overstated.','significance',NULL,'"Significant" → "significance" (adjective → noun, suffix -ance). → The significance of this finding.','easy'),
  (cid,3,18,'multiple_choice','The study measured the _____ of the drug in reducing inflammation.','effectiveness','["effective","effectively","effectiveness","effected"]','"Effective" → "effectiveness" (suffix -ness). → the effectiveness of the drug.','easy'),
  (cid,3,19,'gap_fill','The _____ (complex) of the problem requires interdisciplinary collaboration.','complexity',NULL,'"Complex" → "complexity" (suffix -ity). → The complexity of the problem.','medium'),
  (cid,3,20,'multiple_choice','The researchers examined the _____ of the new vaccine across different age groups.','efficacy','["efficacious","efficiently","efficacy","efficiencies"]','"Efficacious" → "efficacy" (specialized adjective → noun form). → the efficacy of the vaccine.','hard'),
  (cid,3,21,'gap_fill','The _____ (diverse) of species in tropical rainforests far exceeds that in temperate zones.','diversity',NULL,'"Diverse" → "diversity" (suffix -ity). → The diversity of species.','easy'),
  (cid,3,22,'multiple_choice','The _____ of the policy has been questioned by several independent economists.','validity','["valid","validly","validity","validated"]','"Valid" → "validity" (suffix -ity). → The validity of the policy.','medium'),
  (cid,3,23,'gap_fill','The _____ (creative) displayed by the participants surprised the research team.','creativity',NULL,'"Creative" → "creativity" (suffix -ity). → The creativity displayed by the participants.','easy'),
  (cid,3,24,'multiple_choice','The paper discusses the _____ of existing healthcare systems to meet growing demand.','inability','["unable","inability","not able","disabling"]','"Unable" → "inability" (prefix + noun form). → the inability of existing systems.','medium'),

  -- BLOCK 4: Nominalization in Academic Sentences – Transformation
  (cid,4,25,'multiple_choice','Which sentence uses nominalization more effectively (academic style)?','The rapid growth of urban populations has increased the demand for affordable housing.','["Urban populations are rapidly growing, so there is more demand for housing.","The rapid growth of urban populations has increased the demand for affordable housing.","Urban populations have rapidly grown and now there is more demand for affordable housing.","Because urban populations grow rapidly, housing demand has increased."]','Nominalization creates more formal, compact academic prose. → "the rapid growth" instead of "are rapidly growing."','medium'),
  (cid,4,26,'gap_fill','Rewrite using nominalization: "Scientists discovered that the drug reduced inflammation significantly." → The _____ of the drug''s ability to _____ inflammation was significant.','discovery / reduce',NULL,'Nominalizing "discovered" → "the discovery"; the infinitive "to reduce" replaces "reduced."','hard'),
  (cid,4,27,'multiple_choice','Convert to nominalization: "The government decided to reform the tax system."','The government''s decision to reform the tax system...','["The government decided about reforming tax...","The government''s decision to reform the tax system...","The government made a deciding of the tax system...","The government reformed tax with a decision..."]','"Decided" → "decision." Nominalized form: "The government''s decision to reform..." is more formal.','medium'),
  (cid,4,28,'gap_fill','Nominalize the verb: "The company expanded rapidly." → The rapid _____ (expand) of the company attracted investor attention.','expansion',NULL,'"Expand" → "expansion" (suffix -sion). → The rapid expansion of the company.','medium'),
  (cid,4,29,'multiple_choice','Which version is appropriate for academic writing?','The implementation of the new curriculum has improved student outcomes.','["They implemented a new curriculum and students do better now.","Students are doing better because of implementing a new curriculum.","The implementation of the new curriculum has improved student outcomes.","Because they implemented a new curriculum, students improved."]','"The implementation of the new curriculum" = nominalization. More formal, impersonal, and appropriate for academic writing.','medium'),
  (cid,4,30,'gap_fill','Nominalize the adjective: "The data is reliable." → The _____ (reliable) of the data was confirmed by two independent audits.','reliability',NULL,'"Reliable" → "reliability" (suffix -ity). → The reliability of the data was confirmed.','easy'),
  (cid,4,31,'multiple_choice','Choose the correct nominalization: "Researchers analyzed the effects of deforestation."','The analysis of the effects of deforestation...','["The analyzing of the effects of deforestation...","The analyzed effects of deforestation...","The analysis of the effects of deforestation...","The analyses the effects of deforestation..."]','"Analyzed" → "analysis." → The analysis of the effects of deforestation.','medium'),
  (cid,4,32,'gap_fill','Nominalize the verb: "The committee approved the budget." → The _____ (approve) of the budget was unanimous.','approval',NULL,'"Approve" → "approval" (suffix -al). → The approval of the budget was unanimous.','medium'),

  -- BLOCK 5: TOEFL Academic – Nominalizations in Reading Passages
  (cid,5,33,'gap_fill','[TOEFL Reading] The _____ (accumulate) of greenhouse gases in the atmosphere is accelerating climate change.','accumulation',NULL,'"Accumulate" → "accumulation." → The accumulation of greenhouse gases.','medium'),
  (cid,5,34,'multiple_choice','[TOEFL Reading] The _____ of the study''s findings to real-world contexts remains an open question.','applicability','["apply","application","applicability","applicable"]','"Applicable" → "applicability" (suffix -ity). → The applicability of the findings.','hard'),
  (cid,5,35,'gap_fill','[TOEFL Reading] The _____ (reduce) in carbon emissions achieved by the protocol exceeded initial projections.','reduction',NULL,'"Reduce" → "reduction." → The reduction in carbon emissions.','easy'),
  (cid,5,36,'multiple_choice','[TOEFL Reading] _____ of the data revealed a statistically significant pattern across all three trials.','Examination','["Examine","Examining","Examination","Examined"]','As a nominalized subject: "Examination of the data revealed..." This is typical academic style.','medium'),
  (cid,5,37,'gap_fill','[TOEFL Listening] The professor emphasized the _____ (important) of replicating experiments before drawing conclusions.','importance',NULL,'"Important" → "importance." → the importance of replicating experiments.','easy'),
  (cid,5,38,'multiple_choice','[TOEFL Reading] The _____ of microplastics in ocean ecosystems poses a long-term threat to marine biodiversity.','proliferation','["proliferate","proliferating","proliferation","proliferated"]','"Proliferate" → "proliferation." → The proliferation of microplastics.','hard'),
  (cid,5,39,'gap_fill','[TOEFL Reading] The _____ (measure) of sea-level rise is complicated by local geological factors.','measurement',NULL,'"Measure" → "measurement." → The measurement of sea-level rise.','easy'),
  (cid,5,40,'multiple_choice','[TOEFL Reading] The study calls for further _____ into the long-term effects of social media use on adolescents.','investigation','["investigate","investigating","investigation","investigated"]','"Investigate" → "investigation." → further investigation into the effects.','easy'),

  -- BLOCK 6: TOEFL Academic – Recognizing Nominalizations in Text
  (cid,6,41,'multiple_choice','[TOEFL Reading] In the sentence "The establishment of national parks represented a major achievement in conservation," which words are nominalizations?','"establishment" and "achievement"','["\"national\" and \"major\"","\"establishment\" and \"achievement\"","\"represented\" and \"conservation\"","\"parks\" and \"conservation\""]','"Establishment" (establish → -ment) and "achievement" (achieve → -ment) are both nominalizations.','medium'),
  (cid,6,42,'gap_fill','[TOEFL Reading] Identify and replace the nominalization: "The _____ (fail) of the experiment led to a complete redesign of the methodology." → failure','failure',NULL,'"Fail" → "failure." → The failure of the experiment led to a redesign.','easy'),
  (cid,6,43,'multiple_choice','[TOEFL Reading] Which sentence makes better use of nominalization for academic writing?','The deterioration of coral reefs is a direct consequence of rising ocean temperatures.','["Coral reefs are deteriorating because ocean temperatures are rising.","The deterioration of coral reefs is a direct consequence of rising ocean temperatures.","Ocean temperatures rise and so coral reefs deteriorate.","Because ocean temperatures rise, coral reefs deteriorate."]','"The deterioration" and "a direct consequence" are nominalizations that create formal, dense academic style.','hard'),
  (cid,6,44,'gap_fill','[TOEFL Listening] The professor described the _____ (vary) in results as the most challenging aspect of the study.','variation',NULL,'"Vary" → "variation." → the variation in results.','medium'),
  (cid,6,45,'multiple_choice','[TOEFL Reading] Transform: "People are increasingly consuming processed food, which is causing health problems." Best academic version:','The increasing consumption of processed food is causing significant health problems.','["People increasingly consuming processed food cause health problems.","The increasingly consumption of processed food causes health problems.","The increasing consumption of processed food is causing significant health problems.","Increasing consuming of processed food causes health."]','"Consumption" nominalizes "consuming." "Increasing" (adjective) modifies the noun phrase.','hard'),
  (cid,6,46,'gap_fill','[TOEFL Reading] The _____ (observe) that migration patterns are shifting has significant implications for conservation.','observation',NULL,'"Observe" → "observation." → The observation that migration patterns are shifting.','medium'),
  (cid,6,47,'multiple_choice','[TOEFL Reading] "The implementation, modification, and evaluation of educational policy require coordinated effort." How many nominalizations appear in this sentence?','Three','["One","Two","Three","Four"]','"Implementation" (implement), "modification" (modify), and "evaluation" (evaluate) are all nominalizations.','medium'),
  (cid,6,48,'gap_fill','[TOEFL Reading] The _____ (clarify) of this point is essential before the argument can proceed.','clarification',NULL,'"Clarify" → "clarification" (suffix -tion). → The clarification of this point.','medium'),

  -- BLOCK 7: TOEFL Academic – Common Suffix Patterns
  (cid,7,49,'multiple_choice','[TOEFL Reading] Which group correctly nominalizes all three words?','investigate → investigation; apply → application; specify → specification','["investigate → investigment; apply → appliance; specify → specifying","investigate → investigation; apply → application; specify → specification","investigate → investigator; apply → applier; specify → specifier","investigate → investigating; apply → applying; specify → specifying"]','All three use the -tion/-ation suffix for verb → noun nominalization.','medium'),
  (cid,7,50,'gap_fill','[TOEFL Reading] The _____ (require) for candidates to hold a postgraduate degree has been debated.','requirement',NULL,'"Require" → "requirement" (suffix -ment). → The requirement for candidates.','easy'),
  (cid,7,51,'multiple_choice','[TOEFL Reading] Which nominalization is formed correctly?','The assessment of student learning outcomes was positive.','["The assess of student learning outcomes was positive.","The assessment of student learning outcomes was positive.","The assession of student learning outcomes was positive.","The assessment student learning outcomes was positive."]','"Assess" → "assessment" (suffix -ment). → The assessment of student learning outcomes.','easy'),
  (cid,7,52,'gap_fill','[TOEFL Reading] A key _____ (assume) of the model is that demand remains constant over time.','assumption',NULL,'"Assume" → "assumption" (suffix -ption). → A key assumption of the model.','medium'),
  (cid,7,53,'multiple_choice','[TOEFL Listening] The professor discussed the _____ of the new data into the existing theoretical framework.','integration','["integrate","integrating","integration","integrated"]','"Integrate" → "integration." → the integration of the new data into the framework.','medium'),
  (cid,7,54,'gap_fill','[TOEFL Reading] The _____ (oppose) from local communities delayed the construction of the pipeline.','opposition',NULL,'"Oppose" → "opposition" (suffix -tion). → The opposition from local communities.','medium'),
  (cid,7,55,'multiple_choice','[TOEFL Reading] "The _____ of the theory was met with skepticism by the scientific community."','proposition','["propose","proposing","proposition","proposed"]','"Propose" → "proposition" (suffix -tion). → The proposition of the theory.','hard'),
  (cid,7,56,'gap_fill','[TOEFL Reading] The _____ (stable) of the region has improved since the peace agreement was signed.','stability',NULL,'"Stable" → "stability" (suffix -ity). → The stability of the region.','easy'),

  -- BLOCK 8: TOEFL Academic – Noun Phrases & Academic Register
  (cid,8,57,'gap_fill','[TOEFL Reading] Rewrite formally: "The way the economy grew in the 1990s surprised economists." → The _____ of the economy in the 1990s surprised economists.','growth',NULL,'"Grew" → "growth" (irregular nominalization). → The growth of the economy.','medium'),
  (cid,8,58,'multiple_choice','[TOEFL Reading] Which nominalized noun phrase is most appropriate for an academic paper?','an examination of the relationship between diet and cognitive decline','["looking at how diet affects cognitive decline","an examination of the relationship between diet and cognitive decline","checking how diet and cognitive decline are related","seeing if diet affects how the brain works"]','"An examination of the relationship" uses nominalizations appropriate for formal academic writing.','medium'),
  (cid,8,59,'gap_fill','[TOEFL Reading] The _____ (refuse) of the government to act on early warnings worsened the crisis.','refusal',NULL,'"Refuse" → "refusal" (suffix -al). → The refusal of the government to act.','medium'),
  (cid,8,60,'multiple_choice','[TOEFL Reading] Academic texts often prefer nominalization because it:','creates a more formal, impersonal, and information-dense style','["makes sentences shorter and simpler","creates a more formal, impersonal, and information-dense style","avoids the use of adjectives","makes the text easier for non-native speakers to understand"]','Nominalization allows more information to be packed into a noun phrase, creating the dense, impersonal style typical of academic writing.','hard'),
  (cid,8,61,'gap_fill','[TOEFL Reading] The _____ (commit) of organizations to sustainability goals has increased significantly.','commitment',NULL,'"Commit" → "commitment" (suffix -ment). → The commitment of organizations to sustainability goals.','easy'),
  (cid,8,62,'multiple_choice','[TOEFL Reading] Transform into academic style: "Researchers have concluded that exercise improves mental health."','The conclusion that exercise improves mental health has been reached by researchers.','["Researchers concluding exercise improves mental health.","The conclusion that exercise improves mental health has been reached by researchers.","Researchers have made conclusion about exercise and mental health.","Exercise improving mental health is the conclusion of researchers."]','"Conclusion" nominalizes "concluded." Passive construction adds formality. → The conclusion that exercise improves mental health has been reached...','hard'),
  (cid,8,63,'gap_fill','[TOEFL Reading] The _____ (emerge) of new variants has complicated vaccination strategies worldwide.','emergence',NULL,'"Emerge" → "emergence." → The emergence of new variants.','medium'),
  (cid,8,64,'multiple_choice','[TOEFL Reading] Which suffix does NOT typically form a nominalization from a verb?','-ful','["-tion","-ment","-ance","-ful"]','"-ful" forms adjectives (e.g., helpful), not nominalizations from verbs. -tion, -ment, and -ance are common nominalization suffixes.','medium'),

  -- BLOCK 9: TOEFL Speaking Tasks
  (cid,9,65,'production','[TOEFL Speaking — 45s] The reading passage discusses the expansion of urban areas into natural habitats. The lecture argues that this development has caused a significant reduction in biodiversity. Summarize the main points of the lecture and explain how they relate to the reading. Use nominalized forms where possible (e.g., "expansion," "reduction," "development"). You have 45 seconds to respond.','',NULL,'Target: "The expansion of cities..." "The reduction in biodiversity..." "The development of land..."','hard'),
  (cid,9,66,'production','[TOEFL Speaking — 45s] Do you agree or disagree with the following statement: "The introduction of technology into the classroom has improved the quality of education." Use specific reasons and examples. Try to use at least two nominalized forms in your response. You have 45 seconds.','',NULL,'Practice: "The introduction of technology..." "The improvement of student engagement..." "The reduction of teacher workload..."','medium'),
  (cid,9,67,'production','[TOEFL Speaking — 45s] Describe a significant achievement in science or technology from the last 50 years. Explain what it was, how it was accomplished, and what its significance is for society. Use nominalized language in your response. You have 45 seconds.','',NULL,'Use: "The development of..." "The achievement of..." "The application of..." "The significance of..."','hard'),

  -- BLOCK 10: TOEFL Writing Tasks
  (cid,10,68,'production','[TOEFL Writing] The implementation of stricter environmental regulations often faces opposition from industry. However, many argue that the protection of natural resources is essential for long-term economic stability. Discuss the tension between economic development and environmental protection. Use nominalized language throughout your response. Write at least 150 words.','',NULL,'Target nominalizations: "implementation," "opposition," "protection," "development," "stability," "regulation," "deterioration."','hard'),
  (cid,10,69,'production','[TOEFL Writing] The advancement of artificial intelligence has led to significant changes in the employment market. Some economists predict the elimination of many traditional jobs, while others believe that the creation of new industries will offset these losses. Discuss both perspectives and give your own opinion. Write at least 150 words. Use nominalized forms throughout.','',NULL,'Targets: "advancement," "elimination," "creation," "transformation," "automation," "displacement," "development."','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write an academic paragraph (150+ words) arguing either for or against the following statement: "The privatization of public services such as healthcare and education leads to a deterioration in the quality of those services." Use at least SIX different nominalizations (e.g., privatization, deterioration, provision, etc.) and structure your paragraph with a clear claim, evidence, and conclusion.','',NULL,'Target nominalizations: "privatization," "deterioration," "provision," "implementation," "reduction," "improvement," "investment," "allocation."','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
